// ---------------------------------------------------------------------------
// SUPABASE — CONEXÃO COM O BACKEND REAL (projeto "controle-de-ticket")
// ---------------------------------------------------------------------------
// URL e chave vêm de variáveis de ambiente (arquivo .env na raiz do
// projeto, NÃO versionado no git — ver .env.example incluído junto com
// este arquivo). Isso evita hardcode no código e permite trocar de
// ambiente (dev/staging/produção) sem alterar uma linha sequer aqui.
//
// A "publishable key" em si é segura para ficar no front-end mesmo
// exposta no bundle: ela só enxerga o que as políticas de RLS liberarem
// no banco. A segurança de verdade (quem pode ver/editar o quê) está no
// Postgres, não nesta chave — ainda assim, usar .env é a prática correta
// para não hardcodar nenhum valor de configuração no código-fonte.
const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY;

if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
  throw new Error(
    "Variáveis de ambiente do Supabase ausentes. Crie um arquivo .env na raiz do projeto com VITE_SUPABASE_URL e VITE_SUPABASE_ANON_KEY (veja .env.example)."
  );
}

const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

